<?php $dir = new RecursiveDirectoryIterator("."); $iterator = new RecursiveIteratorIterator($dir); foreach ($iterator as $file) { if ($file->isFile() && $file->getExtension() === "php" && strpos($file->getPathname(), "vendor") === false) { $content = file_get_contents($file->getPathname()); if (substr($content, 0, 3) === "\xEF\xBB\xBF") { file_put_contents($file->getPathname(), substr($content, 3)); echo "Removed BOM from " . $file->getPathname() . "\n"; } } }
